/* Selector targets an element */
h1 {
  color: #1a1a2e;
  font-size: 2rem;
  margin-bottom: 1rem;
}

/* Class selector */
.card {
  padding: 1.5rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.5rem;
  margin: 1rem 0;
}

/* Box model demonstration */
.box {
  width: 200px;       /* content width */
  padding: 16px;      /* space inside border */
  border: 2px solid #333; /* visible border */
  margin: 24px;       /* space outside border */
}

